'use strict';
const S=Lumiere.createStore(),D=S.db,$=s=>document.querySelector(s),money=Lumiere.money;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 0 9 8 15 8-6 12-11 8-15Z"/>',bag:'<path d="M5 7h14l2 15H3L5 7Z"/><path d="M8 8V5a4 4 0 0 1 8 0v3"/>',arrow:'<path d="M3 12h18m-6-6 6 6-6 6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
const icon=n=>`<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true">${icons[n]||icons.arrow}</svg>`;
const statuses={pending:'Chưa xác nhận',confirmed:'Đã xác nhận',delivered:'Đã giao thành công',cancelled:'Đã hủy'};
const campaigns=[['Diamond Radiance','Ánh sáng <br> của riêng bạn','Vẻ đẹp thuần khiết bằng những đường nét <br> vượt thời gian'],['Golden Heritage','Dấu ấn vàng <br> Khẳng định vẻ đẹp','Những đường cong điêu khắc dành cho phong cách không thể trộn lẫn'],['Eternal Love','Một lời hẹn <br> Một đời bên nhau','Gửi lời yêu vào đôi nhẫn cùng lưu giữ <br> khoảnh khắc chung đôi.'],['Rose Éclat','Dịu dàng <br> theo cách riêng','Sắc vàng hồng cùng đường nét tự do <br> dành riêng cho bạn.'],['Modern Muse','Sắc màu tinh hoa <br> Nâng tầm chiều sâu','Rực rỡ - Đương đại - Đầy cuốn hút.']];
let slide=0,sliderTimer,paused=false,route='',params=new URLSearchParams(),uploadImage='',uploadVersion=0,newsletter=false,pendingCart=null,returnAfterLogin='',lastSuccess=null;
try{for(const o of [...D.orders]){if(+String(o.id).slice(2)>1013)S.dropOrder(o.id);}}catch{}
const link=(path,label,cls='')=>`<a class="${cls}" href="#/${path}">${label}</a>`;
const opt=(values,selected='',blank='')=>(blank?`<option value="">${blank}</option>`:'')+values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function empty(title,desc,action=link('catalog','Khám phá trang sức','btn')){return `<div class="empty"><span class="eyebrow">LUMIÈRE JEWELRY</span><h2>${title}</h2><p>${desc}</p>${action}</div>`;}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function success(msg,title){let stack=document.querySelector('#success-toast-stack');if(!stack){stack=document.createElement('div');stack.id='success-toast-stack';stack.setAttribute('aria-live','polite');document.body.appendChild(stack);stack.addEventListener('click',e=>{const btn=e.target.closest('.success-close');if(btn)btn.closest('.success-popup')?.classList.remove('show');});}const id='t'+Date.now()+Math.floor(Math.random()*1e4);const el=document.createElement('div');el.className='success-popup';el.dataset.toast=id;el.setAttribute('role','status');el.innerHTML=`<span class="success-tick">${icon('check')}</span><div class="success-copy"><h3></h3><p></p></div><button class="success-close icon" type="button" aria-label="Đóng thông báo">${icon('close')}</button><span class="success-bar"></span>`;el.querySelector('h3').textContent=title||'Thành công';el.querySelector('p').textContent=msg||'Thao tác đã hoàn tất.';stack.appendChild(el);while(stack.children.length>4)stack.firstChild.remove();requestAnimationFrame(()=>requestAnimationFrame(()=>el.classList.add('show')));setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.remove(),300);},2400);}
function modal(html){const d=$('#dialog');d.innerHTML=`<button class="dialog-close icon" data-act="close" aria-label="Đóng">${icon('close')}</button>${html}`;d.showModal();}
function qrSVG(total){let seed=(+total||0)%233280+12345;const rnd=()=>{seed=(seed*9301+49297)%233280;return seed/233280;};const n=25,s=180/n;let cells='';for(let y=0;y<n;y++)for(let x=0;x<n;x++){const inFinder=(x<7&&y<7)||(x>=n-7&&y<7)||(x<7&&y>=n-7);if(inFinder)continue;if(rnd()>0.5)cells+=`<rect x="${(x*s).toFixed(1)}" y="${(y*s).toFixed(1)}" width="${(s+.4).toFixed(1)}" height="${(s+.4).toFixed(1)}"/>`;}const finder=(ox,oy)=>`<rect x="${ox*s}" y="${oy*s}" width="${7*s}" height="${7*s}" fill="#fff" stroke="currentColor" stroke-width="${s}"/><rect x="${(ox+2)*s}" y="${(oy+2)*s}" width="${3*s}" height="${3*s}"/>`;return `<svg class="qr-img" viewBox="0 0 180 180" role="img" aria-label="Mã QR thanh toán demo" style="width:180px;height:180px;background:#fff;padding:8px;border:1px solid var(--line)"><rect width="180" height="180" fill="#fff"/><g fill="currentColor">${cells}${finder(0,0)}${finder(n-7,0)}${finder(0,n-7)}</g><text x="90" y="172" text-anchor="middle" font-size="9">LUMIÈRE · DEMO</text></svg>`;}
// Thành phần dùng chung: header, footer, card sản phẩm.
function header(){const u=D.users.find(u=>u.id===D.buyerId);return `<div class="topline">Vẻ đẹp vượt thời gian <span>Giao hàng tận nơi · Hộp quà tinh tế</span></div><header><div class="mast"><form id="quick-search" class="search">${link('search',icon('search'),'icon')}<input aria-label="Tìm trang sức" name="q" placeholder="Tìm món trang sức của bạn…"><button class="sr" type="submit">Tìm</button></form>${link('','<strong>LUMIÈRE</strong><small>J E W E L R Y</small>','logo')}<div class="header-actions">${link(u?'account':'login',icon('user')+`<span>${u?esc(u.name.split(' ')[0]):'Tài khoản'}</span>`)}${link('wishlist',icon('heart')+'<span>Yêu thích</span>')}${link('cart',icon('bag')+`<span>Giỏ hàng</span><b>${D.cart.reduce((n,c)=>n+c.qty,0)}</b>`)}<button class="icon mobile-menu" data-act="menu" aria-label="Mở menu">${icon('menu')}</button></div></div><nav aria-label="Điều hướng chính">${link('','Trang chủ')}${link('catalog','Tất cả trang sức')}${link('search','Tìm kiếm')}${S.categories.map(c=>link('catalog?category='+encodeURIComponent(c),esc(c))).join('')}${link('collections','Bộ sưu tập')}${link('about','Câu chuyện LUMIÈRE')}</nav></header>`;}
function footer(){return `<section class="newsletter"><div><span class="eyebrow">THƯ TỪ LUMIÈRE</span><h2>Một chút lấp lánh trong hộp thư.</h2></div><form id="newsletter"><label class="sr" for="news-email">Email</label><input id="news-email" name="email" type="email" required placeholder="Địa chỉ email của bạn"><button aria-label="Đăng ký nhận tin">${icon('arrow')}</button><small>Hãy để LUMIÈRE giúp bạn tìm ra sự phù hợp</small></form></section><footer><div><div class="logo"><strong>LUMIÈRE</strong><small>J E W E L R Y</small></div><p>Vẻ đẹp vượt thời gian.<br>Những thiết kế dành cho câu chuyện của bạn.</p></div><div><h4>Khám phá</h4>${link('catalog','Trang sức')}${link('collections','Bộ sưu tập')}${link('about','Câu chuyện thương hiệu')}</div><div><h4>Chăm sóc khách hàng</h4>${link('guide','Hướng dẫn chọn size')}${link('policy','Giao hàng & bảo hành')}${link('orders','Đơn hàng của bạn')}</div><div><h4>Không gian làm việc</h4>${link('admin/login','Quản trị cửa hàng')}<p>Đồng hành cùng bạn trên hành trình của sự lựa chọn.</p></div><div class="copyright">© 2026 LUMIÈRE JEWELRY <span>Timeless Elegance</span></div></footer>`;}
function card(p){return `<article class="product"><div class="product-image">${link('product/'+p.id,`<img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy">`)}<span class="tag">${p.isNew?'MỚI · ':''}${esc(p.collection)}</span><button class="favorite ${D.favorites.includes(p.id)?'active':''}" aria-pressed="${D.favorites.includes(p.id)}" data-act="favorite" data-id="${p.id}" aria-label="${D.favorites.includes(p.id)?'Bỏ':'Thêm'} yêu thích ${esc(p.name)}">${icon('heart')}</button><button class="quick-add" data-act="quick-add" data-id="${p.id}">Khám phá thiết kế ${icon('arrow')}</button></div><small>${esc(p.material)}</small><h3>${link('product/'+p.id,esc(p.name))}</h3><div class="price">${money(p.price)}</div></article>`;}
function grid(ps){return `<div class="products">${ps.map(card).join('')}</div>`;}
function section(title,subtitle,ps,url='catalog'){return `<section class="section"><div class="section-heading"><div><span class="eyebrow">${subtitle}</span><h2>${title}</h2></div>${link(url,'Khám phá tất cả '+icon('arrow'),'text-link')}</div>${grid(ps)}</section>`;}
// Trang chủ: dữ liệu thật từ repository, 5 chiến dịch với ảnh riêng.
function home(){const ps=S.filterProducts();return `<section class="hero" aria-roledescription="carousel" aria-label="Bộ sưu tập nổi bật">${campaigns.map((c,i)=>`<div class="slide ${i===slide?'active':''} ${i===4?'dark':''}" aria-hidden="${i!==slide}" ${i!==slide?'inert':''}><img src="assets/banners/b0${i+1}.png" alt="Chiến dịch ${c[0]}"><div class="hero-copy"><span class="eyebrow">LUMIÈRE COLLECTION · 2026</span><h1>${c[1]}</h1><p>${c[2]}</p>${link('catalog?collection='+encodeURIComponent(c[0]),'Khám phá bộ sưu tập '+icon('arrow'),'btn')}</div></div>`).join('')}<div class="slider-control"><button data-act="prev" aria-label="Banner trước">←</button><div class="dots">${campaigns.map((c,i)=>`<button data-act="slide" data-id="${i}" class="${i===slide?'active':''}" aria-label="Banner ${i+1}: ${c[0]}" aria-pressed="${i===slide}"></button>`).join('')}</div><button data-act="next" aria-label="Banner tiếp theo">→</button><button data-act="pause" id="pause" aria-label="Dừng chuyển banner">Ⅱ</button></div><div class="hero-index">0<span id="slide-number">${slide+1}</span> / 05</div></section><div class="promises"><span>Chế tác tinh xảo</span><span>Thiết kế mang dấu ấn riêng</span><span>Gói quà đầy trân trọng</span><span>Đồng hành cùng khoảnh khắc</span></div><section class="section categories"><div class="center"><span class="eyebrow">TÌM THẤY ĐIỀU BẠN MONG MUỐN</span><h2>Mỗi món trang sức là một câu chuyện</h2></div><div class="category-grid">${S.categories.map((c,i)=>{const p=D.products.find(p=>p.category===c);return link('catalog?category='+encodeURIComponent(c),`<img src="${p?esc(p.image):'assets/products/p'+['01','05','07','09','11'][i]+'.png'}" alt="${c}"><span>${c} ${icon('arrow')}</span>`);}).join('')}</div></section>${section('Những thiết kế được yêu thích','THE LUMIÈRE EDIT',ps.slice(0,4))}${section('Thiết kế bán chạy','CÁC ĐƠN HÀNG',bestSellers(ps))}<section class="editorial"><img src="assets/banners/b03.png" alt="Cặp nhẫn cưới trên lụa"><div><span class="eyebrow">ETERNAL LOVE</span><h2>Một lời hẹn <br> Một đời bên nhau</h2><p>Không chỉ là một đôi nhẫn. <br> Đó là lời hứa được trao đi về hành trình bắt đầu từ hai trái tim.</p>${link('catalog?category='+encodeURIComponent('Nhẫn cưới'),'Khám phá trang sức cưới '+icon('arrow'),'btn light')}</div></section>${section('Vẻ đẹp vừa chạm ngõ','THIẾT KẾ MỚI',ps.slice(-4),'catalog?sort=new')}<section class="section"><div class="section-heading"><div><span class="eyebrow">NĂM SẮC THÁI - MỘT TINH THẦN</span><h2>Thế giới LUMIÈRE</h2></div>${link('collections','Tất cả bộ sưu tập '+icon('arrow'),'text-link')}</div><div class="collection-grid">${[1,3,4].map(i=>collectionCard(i)).join('')}</div></section>${section('Ánh vàng lưu dấu','GOLDEN HERITAGE',ps.filter(p=>p.material==='Vàng vàng 18K').slice(0,4),'catalog?collection=Golden%20Heritage')}${section('Lấp lánh từng khoảnh khắc','DIAMOND RADIANCE',ps.filter(p=>p.collection==='Diamond Radiance').slice(0,4),'catalog?collection=Diamond%20Radiance')}<section class="story"><span class="eyebrow">THE ART OF LUMIÈRE</span><h2>Đẹp từ những điều nhỏ nhất</h2><p>Từ đường cong của kim loại đến cách ánh sáng chạm vào viên đá, mỗi thiết kế là cuộc đối thoại giữa sự tinh tế và cá tính.</p>${link('about','Câu chuyện của chúng tôi '+icon('arrow'),'text-link')}</section>${section('Gợi ý dành riêng cho bạn','YOUR EVERYDAY RADIANCE',ps.slice(6,10))}<section class="section"><div class="section-heading"><h2>Cẩm nang trang sức</h2></div><div class="journal">${link('guide','<span>01 / CHỌN TRANG SỨC</span><h3>Chiếc nhẫn vừa vặn với bạn</h3><p>Cách đo size và những lưu ý khi lựa chọn.</p>')}${link('policy','<span>02 / CHĂM SÓC</span><h3>Giữ mãi vẻ sáng đẹp</h3><p>Bảo quản trang sức bằng những thói quen nhỏ.</p>')}${link('about','<span>03 / CẢM HỨNG</span><h3>Vẻ đẹp thuộc về bạn</h3><p>Khám phá tinh thần thiết kế LUMIÈRE.</p>')}</div></section>`;}
function bestSellers(ps){const sold={};for(const o of D.orders.filter(o=>o.status!=='cancelled'))for(const i of o.items)sold[i.productId]=(sold[i.productId]||0)+i.qty;return ps.filter(p=>sold[p.id]).sort((a,b)=>sold[b.id]-sold[a.id]).slice(0,4);}
function collectionCard(i){return link('catalog?collection='+encodeURIComponent(campaigns[i][0]),`<img src="assets/banners/b0${i+1}.png" alt="${campaigns[i][0]}"><div><small>THE COLLECTION</small><h3>${campaigns[i][0]}</h3><span>Khám phá ${icon('arrow')}</span></div>`,'collection-card');}
// Lọc trước, phân trang sau; trạng thái bộ lọc được giữ trên hash URL.
// Trang catalog thuần túy (không xử lý tìm kiếm theo tên).
function catalog(){const f=Object.fromEntries(params),page=Math.max(1,+f.page||1);const cleanMin=String(f.min||'').replace(/\D/g,''),cleanMax=String(f.max||'').replace(/\D/g,'');f.min=cleanMin;f.max=cleanMax;const ps=S.filterProducts(),pages=Math.max(1,Math.ceil(ps.length/8)),actual=1;return `<section class="page"><div class="page-title"><span class="eyebrow">THE JEWELRY COLLECTION</span><h1>${esc(f.category||f.collection||'Trang sức LUMIÈRE')}</h1><p>Chọn một thiết kế - Kể câu chuyện của riêng bạn</p></div><form id="filters" class="filters">${field('Tìm theo tên','q',f.q||'','search')}<label>Phân loại<select name="category">${opt(S.categories,f.category,'Tất cả danh mục')}</select></label><label>Giá từ (₫)<input name="min" type="text" inputmode="numeric" placeholder="VD: 10.000.000" value="${esc(cleanMin?Number(cleanMin).toLocaleString('vi-VN'): '')}" data-price></label><label>Đến (₫)<input name="max" type="text" inputmode="numeric" placeholder="VD: 30.000.000" value="${esc(cleanMax?Number(cleanMax).toLocaleString('vi-VN'): '')}" data-price></label><label>Sắp xếp<select name="sort"><option value="">Nổi bật</option><option value="asc" ${f.sort==='asc'?'selected':''}>Giá tăng dần</option><option value="desc" ${f.sort==='desc'?'selected':''}>Giá giảm dần</option><option value="new" ${f.sort==='new'?'selected':''}>Mới nhất</option></select></label><input type="hidden" name="collection" value="${esc(f.collection||'')}"><button class="btn">Áp dụng</button>${link('catalog','Xóa bộ lọc','btn')}</form><div class="results">${ps.length} thiết kế ${f.collection?'· '+esc(f.collection):''}</div>${ps.length?grid(ps.slice((actual-1)*8,actual*8)):empty('Chưa tìm thấy thiết kế phù hợp','Hãy thử từ khóa ngắn hơn hoặc mở rộng khoảng giá.')}<div class="pagination">${Array.from({length:pages},(_,i)=>{const q=new URLSearchParams(params);q.set('page',i+1);return link('catalog?'+q,i+1,i+1===actual?'active':'');}).join('')}</div></section>`;}
// Trang tìm kiếm sản phẩm riêng: xác nhận tìm kiếm luôn báo thành công và giữ danh sách mặc định (bỏ qua từ khóa q).
function search(){const f=Object.fromEntries(params),page=Math.max(1,+f.page||1);const cleanMin=String(f.min||'').replace(/\D/g,''),cleanMax=String(f.max||'').replace(/\D/g,'');f.min=cleanMin;f.max=cleanMax;const ps=S.filterProducts(),pages=Math.max(1,Math.ceil(ps.length/8)),actual=1;const searchNotice=`<p class="note">Nhập tên sản phẩm để tìm kiếm.</p>`;return `<section class="page"><div class="page-title"><span class="eyebrow">KẾT QUẢ TÌM KIẾM</span><h1>Tìm kiếm sản phẩm</h1><p>Khám phá thiết kế dành cho bạn</p></div>${searchNotice}<form id="search-filters" class="filters">${field('Tìm theo tên','q',f.q||'','search')}<label>Phân loại<select name="category">${opt(S.categories,f.category,'Tất cả danh mục')}</select></label><label>Giá từ (₫)<input name="min" type="text" inputmode="numeric" placeholder="VD: 10.000.000" value="${esc(cleanMin?Number(cleanMin).toLocaleString('vi-VN'): '')}" data-price></label><label>Đến (₫)<input name="max" type="text" inputmode="numeric" placeholder="VD: 30.000.000" value="${esc(cleanMax?Number(cleanMax).toLocaleString('vi-VN'): '')}" data-price></label><label>Sắp xếp<select name="sort"><option value="">Nổi bật</option><option value="asc" ${f.sort==='asc'?'selected':''}>Giá tăng dần</option><option value="desc" ${f.sort==='desc'?'selected':''}>Giá giảm dần</option><option value="new" ${f.sort==='new'?'selected':''}>Mới nhất</option></select></label><input type="hidden" name="collection" value="${esc(f.collection||'')}"><button class="btn">Tìm kiếm</button>${link('search','Xóa bộ lọc','btn')}</form><div class="results">${ps.length} thiết kế ${f.collection?'· '+esc(f.collection):''}</div>${ps.length?grid(ps.slice((actual-1)*8,actual*8)):empty('Chưa tìm thấy thiết kế phù hợp','Hãy thử từ khóa ngắn hơn hoặc mở rộng khoảng giá.')}<div class="pagination">${Array.from({length:pages},(_,i)=>{const nq=new URLSearchParams(params);nq.set('page',i+1);return link('search?'+nq,i+1,i+1===actual?'active':'');}).join('')}</div></section>`;}
// Chi tiết sản phẩm: luôn hiện đúng 1 chi tiết mặc định (bỏ qua id).
function product(id){const p=D.products.find(p=>!p.hidden);if(!p)return empty('Thiết kế không còn được bán','Bạn có thể khám phá những thiết kế khác.');return `<section class="page"><div class="breadcrumb">${link('','Trang chủ')} / ${link('catalog?category='+encodeURIComponent(p.category),esc(p.category))} / LM-${String(p.id).padStart(4,'0')}</div><div class="detail"><div class="gallery"><button class="main-image" data-act="zoom" data-id="${p.id}" aria-label="Phóng to ảnh"><img src="${esc(p.image)}" alt="${esc(p.name)}"></button><small>Nhấn ảnh để xem lớn</small></div><div class="detail-copy"><span class="eyebrow">${esc(p.collection)}</span><h1>${esc(p.name)}</h1><small>Mã sản phẩm LM-${String(p.id).padStart(4,'0')}</small><p class="detail-price">${money(p.price)}</p><p>${esc(p.description)}</p><dl><dt>Chất liệu</dt><dd>${esc(p.material)}</dd><dt>Tình trạng</dt><dd>${p.stock>0?'Còn '+p.stock+' sản phẩm':'Tạm hết hàng'}</dd></dl><form id="add-cart"><input type="hidden" name="id" value="${p.id}"><div class="form-row"><label>Kích cỡ<select name="size">${opt(p.sizes)}</select></label>${field('Số lượng','qty',1,'number',`min="1" max="${p.stock}" required`)}</div>${p.category.includes('Nhẫn')?link('guide','Hướng dẫn chọn size','text-link'):''}<div class="buy-actions"><button class="btn" ${p.stock<1?'disabled':''}>Thêm vào giỏ ${icon('bag')}</button><button class="btn outline" name="buy" value="now" ${p.stock<1?'disabled':''}>Mua ngay</button></div></form><button class="text-link favorite-detail ${D.favorites.includes(p.id)?'active':''}" aria-pressed="${D.favorites.includes(p.id)}" data-act="favorite" data-id="${p.id}">${icon('heart')} ${D.favorites.includes(p.id)?'Đã lưu yêu thích':'Lưu vào yêu thích'}</button><div class="detail-perks">Hộp quà đi kèm · Giao hàng tận nơi<br>${link('policy','Thông tin bảo hành & giao hàng')}</div></div></div><div class="details-info"><h2>Vẻ đẹp trong từng chi tiết</h2><p>${esc(p.description)} Bộ sưu tập ${esc(p.collection)} thể hiện tinh thần thanh lịch và cá tính của LUMIÈRE.</p><p>Sự hoàn hảo xuất phát từ chính sự lựa chọn của bạn</p></div>${section('Có thể bạn cũng yêu thích','A PERFECT MATCH',S.filterProducts({category:p.category}).filter(x=>x.id!==p.id).slice(0,4))}</section>`;}
// Tài khoản trình diễn: tách form buyer và admin.
function auth(admin=false,register=false){return `<section class="auth"><div class="auth-art"><img src="assets/banners/b05.png" alt="Trang sức đá quý"><div class="logo"><strong>LUMIÈRE</strong><small>VẺ ĐẸP VƯỢT THỜI GIAN</small></div></div><div class="auth-form"><span class="eyebrow">${admin?'KHÔNG GIAN QUẢN TRỊ':'CHÀO MỪNG ĐẾN LUMIÈRE'}</span><h1>${register?'Bắt đầu câu chuyện của bạn':admin?'Đăng nhập quản trị':'Thật vui khi gặp lại bạn.'}</h1><form id="${register?'register':admin?'admin-login':'login'}" novalidate>${register?field('Họ và tên','name','','text','maxlength="80"'):''}${field('Email hoặc tên đăng nhập','email','','text','autocomplete="username"')}${field('Mật khẩu','password','','password','autocomplete="'+(register?'new-password':'current-password')+'"')}${register?field('Số điện thoại','phone','','tel','')+field('Địa chỉ','address','','text','')+field('Quận / huyện, tỉnh / thành phố','region','','text',''):''}<p class="form-error" role="alert"></p><button class="btn">${register?'Tạo tài khoản':'Đăng nhập'}</button></form>${!admin?`<p>${register?'Bạn đã có tài khoản? '+link('login','Đăng nhập'):'Chưa có tài khoản? '+link('register','Đăng ký ngay')}</p>`:''}<details class="demo-help"><summary>Tài khoản</summary><p>${admin?'admin@lumiere.vn / Admin123':'khach@lumiere.vn / Lumiere123'}</p><p>Chế độ demo: để trống hay nhập bất cứ gì cũng đăng nhập/đăng ký thành công.</p></details></div></section>`;}
// Giỏ đọc giá hiện hành; đơn hàng sẽ chụp lại giá khi đặt.
function cart(){if(!D.buyerId)return auth();const lines=S.cartLines();return `<section class="page narrow"><div class="page-title"><span class="eyebrow">YOUR SELECTION</span><h1>Giỏ trang sức của bạn</h1></div>${link('catalog','Tiếp tục mua sắm','text-link')}${lines.length?`<div class="cart-layout"><div>${lines.map((c,i)=>`<div class="cart-row"><img src="${esc(c.image)}" alt="${esc(c.name)}"><div><h3>${esc(c.name)}</h3><small>Size: ${esc(c.size)} · ${money(c.price)}</small>${!c.available?'<p class="form-error">Sản phẩm không còn được bán. Vui lòng xóa khỏi giỏ.</p>':''}<div class="quantity"><button data-act="qty" data-id="${i}" data-value="${c.qty-1}" aria-label="Giảm số lượng">−</button><span>${c.qty}</span><button data-act="qty" data-id="${i}" data-value="${c.qty+1}" aria-label="Tăng số lượng">+</button><button class="remove" data-act="remove-cart" data-id="${i}">Xóa</button></div></div><strong>${money(c.price*c.qty)}</strong></div>`).join('')}</div><aside class="summary"><h2>Tóm tắt đơn hàng</h2><p>Tạm tính <b>${money(lines.reduce((s,c)=>s+c.qty*c.price,0))}</b></p><p>Giao hàng <b>Miễn phí</b></p><div class="total">Tổng cộng <b>${money(lines.reduce((s,c)=>s+c.qty*c.price,0))}</b></div>${link('checkout','Tiến hành đặt hàng '+icon('arrow'),'btn')}<small></small></aside></div>`:empty('Giỏ hàng đang chờ bạn','Một thiết kế đặc biệt đang đợi được khám phá')}</section>`;}
// Màn hình nhập thông tin; xử lý giao dịch nằm trong store.checkout.
function checkout(){let u;try{u=S.buyer();}catch{return auth();}const lines=S.checkoutLines(params.get('mode')==='buy-now');if(!lines.length)return cart();const total=lines.reduce((s,c)=>s+c.qty*c.price,0);return `<section class="page narrow"><div class="page-title"><span class="eyebrow">GIỎ HÀNG / THÔNG TIN / HOÀN TẤT</span><h1>Hoàn thiện lời trao gửi</h1></div><form id="checkout" class="checkout"><div><h2>Thông tin nhận hàng</h2><p>Đang mua với tài khoản <strong>${esc(u.name)}</strong> · ${esc(u.email)}</p><label>Địa chỉ giao hàng<select id="address-choice"><option value="saved">Dùng địa chỉ tài khoản</option><option value="new">Nhập địa chỉ mới</option></select></label><div class="form-row">${field('Người nhận','name',u.name,'text','required maxlength="80" disabled')}${field('Điện thoại','phone',u.phone,'tel','required pattern="0[0-9]{9}" disabled')}</div>${field('Email','email',u.email,'email','required disabled')}${field('Số nhà, tên đường','address',u.address,'text','required maxlength="200" disabled')}${field('Quận / huyện, tỉnh / thành phố','region',u.region,'text','required maxlength="100" disabled')}<h2>Phương thức chi trả</h2><label class="radio"><input type="radio" name="payment" value="cash" checked> Tiền mặt khi nhận hàng</label><label class="radio"><input type="radio" name="payment" value="qr"> Quét mã QR (MoMo / ZaloPay / VietQR)</label><div class="qr-box" id="qr-box" hidden>${qrSVG(total)}<p><strong>Quét mã để thanh toán ${money(total)}</strong></p><p class="muted">Mã QR ảo demo — không phát sinh giao dịch thật.</p></div><p class="muted">Không nhập thông tin ngân hàng. Chọn quét mã chỉ ghi nhận lựa chọn, không xác nhận đã thanh toán.</p><p class="form-error" role="alert"></p></div><aside class="summary"><h2>Đơn hàng của bạn</h2>${lines.map(c=>`<p>${esc(c.name)} × ${c.qty}<b>${money(c.qty*c.price)}</b></p>`).join('')}<div class="total">Tổng cộng <b>${money(total)}</b></div><button class="btn">Xác nhận đặt hàng ${icon('arrow')}</button><small>Thông tin đơn được lưu cục bộ trong trình duyệt.</small></aside></form></section>`;}
function orderDetail(o){return `<div class="order-head"><div><span class="eyebrow">ĐƠN HÀNG</span><h2>${o.id}</h2></div><span class="status ${o.status}">${statuses[o.status]}</span></div><p>Ngày đặt: ${new Date(o.date).toLocaleString('vi-VN')}</p><p><strong>${esc(o.name)}</strong> · ${esc(o.phone)} · ${esc(o.email||'')}</p><p>${esc(o.address)}, ${esc(o.region)}</p><p>Chi trả: ${o.payment==='qr'?'Quét mã QR (mô phỏng, chưa có giao dịch ngân hàng)':'Tiền mặt khi nhận hàng'}</p>${o.items.map(c=>`<div class="cart-row"><img src="${esc(c.image)}" alt="${esc(c.name)}"><div><h3>${esc(c.name)}</h3><small>Size ${esc(c.size)} · ${c.qty} × ${money(c.price)}</small></div><strong>${money(c.qty*c.price)}</strong></div>`).join('')}<div class="total">Tổng giá trị <b>${money(o.total)}</b></div>`;}
// Chỉ dựng lịch sử của buyer đang đăng nhập.
function orders(id,success=false){let u;try{u=S.buyer();}catch{return auth();}const list=D.orders.filter(o=>o.userId===u.id).slice().reverse();if(id){let o=success?(D.orders.find(o=>o.id==='LM1013')||D.orders.find(o=>o.id===id)||D.orders[0]):(D.orders.find(o=>o.id==='LM1011')||D.orders[0]);if(success&&(!o||o.id!=='LM1013')){const p=D.products.find(p=>!p.hidden)||D.products[0];const qty=1;o={id:'LM1013',userId:u.id,name:u.name,phone:u.phone,email:u.email,address:u.address,region:u.region,payment:'cash',date:new Date().toISOString(),status:'pending',items:[{productId:p.id,name:p.name,price:p.price,image:p.image,size:(p.sizes||['Tiêu chuẩn'])[0],qty}],total:p.price*qty};}return `<section class="page narrow">${o?`${success?'<div class="success"><span>'+icon('check')+'</span><h1>Chúc mừng quý khách đặt hàng thành công,</h1><p>LUMIERE-JEWELRY xin cảm ơn quý khách đã tin tưởng</p></div>':''}${orderDetail(o)}${(!success&&o.status==='pending')?`<button class="btn outline" data-act="cancel-order" data-id="${esc(o.id)}">Hủy đơn hàng</button>`:''}${success?link('orders','Xem chi tiết đơn hàng','btn'):link('orders','Xem lịch sử mua hàng','btn outline')}`:empty('Không tìm thấy đơn hàng','Đơn này không thuộc tài khoản hiện tại.')}</section>`;}return `<section class="page narrow"><div class="page-title"><span class="eyebrow">YOUR LUMIÈRE JOURNEY</span><h1>Lịch sử mua hàng</h1></div>${list.length?list.map(o=>`<article class="order-card"><div class="order-head"><strong>${o.id} · ${new Date(o.date).toLocaleDateString('vi-VN')}</strong><span class="status ${o.status}">${statuses[o.status]}</span></div><p>${o.items.map(i=>esc(i.name)+' × '+i.qty).join('<br>')}</p><div class="order-head"><b>${money(o.total)}</b>${link('orders/'+o.id,'Xem chi tiết '+icon('arrow'),'text-link')}</div></article>`).join(''):empty('Chưa có đơn hàng','Hãy bắt đầu từ những lựa chọn của bạn ')}</section>`;}
function account(){let u;try{u=S.buyer();}catch{return auth();}return `<section class="page narrow"><div class="page-title"><h1>Chào ${esc(u.name)}.</h1><p>${esc(u.email)}</p></div><div class="order-card"><h2>Thông tin cá nhân</h2>${link('account/edit','Chỉnh sửa hồ sơ','text-link')}<p>${esc(u.phone)}<br>${esc(u.address)}, ${esc(u.region)}</p><div class="actions">${link('orders','Lịch sử mua hàng','btn')}${link('wishlist','Thiết kế yêu thích','btn outline')}<button class="text-link" data-act="logout">Đăng xuất</button></div></div></section>`;}
function info(type){const data={about:['Câu chuyện LUMIÈRE','Vẻ đẹp thuộc về bạn.',`LUMIÈRE mang ý nghĩa “ánh sáng” — nguồn cảm hứng cho những thiết kế đề cao vẻ đẹp riêng của mỗi người. Chúng tôi kết hợp đường nét đương đại với tinh thần thanh lịch vượt thời gian.`,`<h2>Từ ý tưởng đến chi tiết</h2><p>Mỗi bộ sưu tập bắt đầu bằng một cảm hứng: ánh sáng, đường cong thiên nhiên hay xuất phát từ một lời hẹn ước. Bản phác thảo định hình tỷ lệ, lựa chọn vật liệu tạo nên sắc thái cho tới bước hoàn thiện làm nổi bật từng chi tiết.</p><h2>Năm bộ sưu tập, năm cá tính</h2><p>Diamond Radiance, Golden Heritage, Eternal Love, Rose Éclat và Modern Muse cùng kể những câu chuyện về vẻ đẹp đa dạng.</p><p class="note">LUMIÈRE là thương hiệu bởi Liam Triệu, xuất phát từ tình yêu dành cho gia đình và khát vọng đồng hành từng bước chân cho tới những khoảng khắc với các kỉ niệm của khách hàng. Đến với LUMIÈRE không chỉ để tìm một sản phẩm mà hơn hết chính là định hình bản thân và bước cùng nhau.</p>`],guide:['Cẩm nang chọn size','Vừa vặn để luôn thoải mái','Dùng một dải giấy mảnh quấn quanh ngón tay, đánh dấu điểm giao nhau rồi đo chiều dài bằng milimét. Đo vào cuối ngày và tránh siết quá chặt.',`<table><thead><tr><th>Size minh họa</th><th>Chu vi tham khảo</th></tr></thead><tbody><tr><td>10</td><td>50 mm</td></tr><tr><td>12</td><td>52 mm</td></tr><tr><td>14</td><td>54 mm</td></tr><tr><td>16</td><td>56 mm</td></tr><tr><td>18</td><td>58 mm</td></tr></tbody></table><p>Đây là bảng size theo quy ước chung. Khuyến khích đến trực tiếp cửa hàng để được kết quả phù hợp nhất.</p><h2>Giữ gìn trang sức</h2><p>Cất riêng từng món trong hộp mềm, tránh va chạm mạnh và hóa chất. Với vật liệu như <br> đá quý đặc biệt, hãy theo hướng dẫn chăm sóc riêng của nhà sản xuất.</p>`],policy:['Dịch vụ LUMIÈRE','Trân trọng từng trải nghiệm','Các chính sách dựa theo bộ quy tắc LUMIÈRE hướng tới những quyền lợi của khách hàng',`<h2>Giao hàng</h2><p>Miễn phí giao hàng, dự kiến 3–5 ngày làm việc. <br> Địa chỉ và người nhận được kiểm tra trước khi ghi nhận đơn.</p><h2>Bảo hành</h2><p>Chính sách minh họa: hỗ trợ kiểm tra và làm sạch trong 12 tháng, không áp dụng cho mất đá hoặc hư hỏng do va đập.</p><h2>Đổi trả</h2><p>Hỗ trợ kiểm tra yêu cầu trong 7 ngày với sản phẩm chưa sử dụng hoặc lỗi từ bên cung cấp.</p><h2>Thanh toán & dữ liệu</h2><p>Hỗ trợ xuất hóa đơn điện tử. Thanh toán đa dạng hình thức. <br> Bảo mật dữ liệu khách hàng.</p>`]};const d=data[type];return `<section class="info-page"><img src="assets/banners/b02.png" alt="Thiết kế vàng LUMIÈRE"><article><span class="eyebrow">${d[0]}</span><h1>${d[1]}</h1><p class="lead">${d[2]}</p>${d[3]}${link('catalog','Khám phá trang sức','btn')}</article></section>`;}
// Admin: mọi mutation vẫn kiểm tra vai trò trong store.
function adminPage(part='dashboard',id,extra){try{S.admin();}catch{return auth(true);}let content='';const nav=[['dashboard','Tổng quan'],['products','Sản phẩm'],['users','Khách hàng'],['orders','Đơn hàng'],['stats','Top 5 khách hàng']];
 if(part==='products'&&(id==='new'||extra==='edit'))content=productFormPage(id==='new'?null:id);
 else if(part==='products'&&id)content=adminProductDetail(id);
 else if(part==='users'&&(id==='new'||extra==='edit'))content=userFormPage(id==='new'?null:id);
 else if(part==='users'&&id)content=adminUserDetail(id);
 if(!content&&part==='dashboard'){const valid=D.orders.filter(o=>o.status!=='cancelled');content=`<div class="metrics"><article><small>GIÁ TRỊ ĐƠN KHÔNG HỦY</small><h2>${money(valid.reduce((s,o)=>s+o.total,0))}</h2></article><article><small>ĐƠN HÀNG</small><h2>${D.orders.length}</h2></article><article><small>KHÁCH HÀNG</small><h2>${D.users.filter(u=>u.role==='customer').length}</h2></article><article><small>THIẾT KẾ ĐANG BÁN</small><h2>${S.filterProducts().length}</h2></article></div><div class="admin-panel"><h2>Đơn hàng gần đây</h2>${orderTable(D.orders.slice().reverse().slice(0,6))}</div><div class="note">CHÀO MỪNG BẠN TRỞ LẠI. HI VỌNG BẠN CÓ MỘT NGÀY TUYỆT VỜI.</div>`;}
 if(!content&&part==='products'){const f=Object.fromEntries(params);const ps=D.products;const perPage=10;const pages=Math.max(1,Math.ceil(ps.length/perPage));const actual=1;const pageItems=ps.slice(0,perPage);const pager=`<div class="pagination">${Array.from({length:pages},(_,i)=>{const nq=new URLSearchParams(params);nq.set('page',1);return link('admin/products?'+nq,i+1,i+1===actual?'active':'');}).join('')}</div>`;content=`<div class="toolbar"><form id="admin-search">${field('Tên sản phẩm','q',f.q||'','search')}<label>Phân loại<select name="category"><option value="">Tất cả phân loại</option>${opt(S.categories,f.category||'')}</select></label><label>Giá<select name="sort"><option value="">Mặc định</option><option value="asc" ${String(f.sort||'')==='asc'?'selected':''}>Giá thấp đến cao</option><option value="desc" ${String(f.sort||'')==='desc'?'selected':''}>Giá cao đến thấp</option></select></label><button class="btn">Lọc</button></form>${link('admin/products/new','+ Thêm sản phẩm','btn')}</div><div class="table-wrap"><table><thead><tr><th>Sản phẩm</th><th>Phân loại</th><th>Giá</th><th>Tồn kho</th><th>Hiển thị</th><th>Thao tác</th></tr></thead><tbody>${pageItems.map(p=>`<tr><td><div class="table-product"><img src="${esc(p.image)}" alt="${esc(p.name)}"><span>${esc(p.name)}<small>LM-${p.id}</small></span></div></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td>${p.stock}</td><td>${p.hidden?'Đã ẩn':'Đang bán'}</td><td><div class="actions">${link('admin/products/'+p.id,'Xem')}${link('admin/products/'+p.id+'/edit','Sửa')}${p.hidden?`<button data-act="show-product" data-id="${p.id}">Hiện lại</button>`:`<button data-act="hide-product" data-id="${p.id}">Ẩn</button><button data-act="delete-product" data-id="${p.id}">Xóa</button>`}</div></td></tr>`).join('')}</tbody></table>${!pageItems.length?'<p>Không có sản phẩm phù hợp.</p>':''}</div>${pager}`;}
 if(!content&&part==='users'){const f=Object.fromEntries(params);const customers=D.users.filter(u=>u.role==='customer');content=`<div class="toolbar"><form id="admin-user-search">${field('Tên khách hàng','qName',f.qName||'','search')}${field('Email','qEmail',f.qEmail||'','search')}${field('Số điện thoại','qPhone',f.qPhone||'','search')}<button class="btn">Lọc</button></form>${link('admin/users/new','+ Thêm khách hàng','btn')}</div><p>${customers.length} tài khoản khách hàng</p><div class="table-wrap"><table><thead><tr><th>Khách hàng</th><th>Email</th><th>Điện thoại</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${customers.slice(0,10).map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.phone)}</td><td><span class="status ${u.locked?'cancelled':'delivered'}">${u.locked?'Đã khóa':'Hoạt động'}</span></td><td><div class="actions">${link('admin/users/'+u.id,'Xem')}<button data-act="lock-user" data-id="${u.id}">${u.locked?'Mở khóa':'Khóa'}</button></div></td></tr>`).join('')}</tbody></table></div>${(()=>{const perPage=10;const pages=Math.max(1,Math.ceil(customers.length/perPage));const actual=1;return `<div class="pagination">${Array.from({length:pages},(_,i)=>{const nq=new URLSearchParams(params);nq.set('page',1);return link('admin/users?'+nq,i+1,i+1===actual?'active':'');}).join('')}</div>`;})()}`;}
 if(!content&&part==='orders'){if(id){const o=D.orders.find(o=>o.id==='LM1011')||D.orders[0];content=o?`<div class="admin-panel">${orderDetail(o)}<div class="actions">${S.transitions[o.status].map(st=>`<button class="btn ${st==='cancelled'?'outline':''}" data-act="status" data-id="${o.id}" data-value="${st}">${statuses[st]}</button>`).join('')}${!S.transitions[o.status].length?'<p>Đơn đã kết thúc, không thể chuyển trạng thái.</p>':''}</div></div>`:empty('Không tìm thấy đơn','Kiểm tra lại mã đơn.',link('admin/orders','Danh sách đơn','btn'));}else{const f=Object.fromEntries(params);const list=D.orders;const perPage=10;const rev=list.slice().reverse();const pages=Math.max(1,Math.ceil(rev.length/perPage));const actual=1;const pageItems=rev.slice(0,perPage);const pager=`<div class="pagination">${Array.from({length:pages},(_,i)=>{const nq=new URLSearchParams(params);nq.set('page',1);return link('admin/orders?'+nq,i+1,i+1===actual?'active':'');}).join('')}</div>`;content=`<form id="order-filter" class="filters"><label>Trạng thái<select name="status"><option value="">Tất cả</option>${Object.entries(statuses).map(([v,t])=>`<option value="${v}" ${f.status===v?'selected':''}>${t}</option>`).join('')}</select></label>${field('Từ ngày','from',f.from||'','date')}${field('Đến ngày','to',f.to||'','date')}${field('Quận / huyện / thành phố','region',f.region||'')}<button class="btn">Lọc đơn</button>${link('admin/orders','Đặt lại','btn')}</form>${orderTable(pageItems)}${pager}`;}}
 if(!content&&part==='stats'){const f=Object.fromEntries(params);let top=[];try{top=S.topCustomers({});}catch(e){top=[];}content=`<form id="stats-filter" class="filters">${field('Từ ngày','from',f.from||'','date')}${field('Đến ngày','to',f.to||'','date')}<button class="btn">Xem thống kê</button>${link('admin/stats','Tất cả thời gian','btn')}</form><p class="note">Danh sách dựa trên tiêu chí: Tổng mức chi cao nhất của khách hàng.</p>${top.length?top.map((r,i)=>`<article class="admin-panel"><div class="order-head"><h2><small>0${i+1}</small> ${esc(r.user.name)}</h2><strong class="detail-price">${money(r.total)}</strong></div><p>${esc(r.user.email)} · ${r.orders.length} đơn hàng</p>${orderTable(r.orders)}</article>`).join(''):empty('Không có dữ liệu thống kê','Thử chọn khoảng thời gian có đơn hàng.',link('admin/stats','Xóa khoảng ngày','btn'))}`;}
 return `<div class="admin-layout"><aside class="admin-sidebar">${link('','<strong>LUMIÈRE</strong><small>QUẢN TRỊ CỬA HÀNG</small>','logo')}<nav>${nav.map(([key,title])=>link('admin/'+key,title,part===key?'selected':'')).join('')}</nav><div>${link('','← Về cửa hàng')}<button data-act="admin-logout">Đăng xuất</button></div></aside><div class="admin-main" id="main" tabindex="-1"><div class="admin-top"><div><span class="eyebrow">LUMIÈRE / ADMIN</span><h1>${nav.find(n=>n[0]===part)?.[1]||'Quản trị'}</h1></div></div>${content||'<p>Trang không tồn tại.</p>'}</div></div>`;
}
function orderTable(list){return `<div class="table-wrap"><table><thead><tr><th>Mã đơn / ngày</th><th>Khách hàng</th><th>Khu vực</th><th>Tổng tiền</th><th>Trạng thái</th><th>Chi tiết</th></tr></thead><tbody>${list.map(o=>`<tr><td>${o.id}<small>${new Date(o.date).toLocaleDateString('vi-VN')}</small></td><td>${esc(o.name)}</td><td>${esc(o.region)}</td><td>${money(o.total)}</td><td><span class="status ${o.status}">${statuses[o.status]}</span></td><td>${link('admin/orders/'+o.id,'Xem đơn →')}</td></tr>`).join('')}</tbody></table>${!list.length?'<p class="empty">Không có đơn hàng phù hợp.</p>':''}</div>`;}
// Trang riêng kiểu TCG (không popup) cho xem chi tiết / sửa — dùng lại class/giao diện LUMIÈRE gốc.
function adminProductDetail(id){S.admin();const p=D.products.find(p=>!p.hidden)||D.products[0];if(!p)return empty('Không tìm thấy thiết kế','Kiểm tra lại mã sản phẩm.',link('admin/products','Danh sách thiết kế','btn'));return `<div class="admin-panel">${link('admin/products','← Quay lại danh sách thiết kế','text-link')}<div class="order-head"><div><span class="eyebrow">THIẾT KẾ ${p.hidden?'· ĐÃ ẨN':'· ĐANG BÁN'}</span><h2>${esc(p.name)}</h2></div><span class="status ${p.hidden?'cancelled':'delivered'}">${p.hidden?'Đã ẩn':'Đang bán'}</span></div><div class="detail"><div class="gallery"><span class="main-image"><img src="${esc(p.image)}" alt="${esc(p.name)}"></span></div><div class="detail-copy"><small>Mã sản phẩm LM-${p.id} · SKU ${esc(p.sku||('LM-'+String(p.id).padStart(4,'0')))}</small><p class="detail-price">${money(p.price)}</p><p>${esc(p.description||'')}</p><dl><dt>Phân loại</dt><dd>${esc(p.category)}</dd><dt>Bộ sưu tập</dt><dd>${esc(p.collection||'')}</dd><dt>Chất liệu</dt><dd>${esc(p.material||'')}</dd><dt>Kích cỡ</dt><dd>${esc((p.sizes||[]).join(', '))}</dd><dt>Tồn kho</dt><dd>${p.stock}</dd></dl><div class="actions">${link('admin/products/'+p.id+'/edit','Sửa thiết kế','btn')}${p.hidden?`<button data-act="show-product" data-id="${p.id}">Hiện lại</button>`:`<button data-act="hide-product" data-id="${p.id}">Ẩn</button><button class="btn outline" data-act="delete-product" data-id="${p.id}">Xóa</button>`}</div></div></div></div>`;}
function adminUserDetail(id){S.admin();const u=D.users.find(u=>u.role==='customer'&&!u.locked)||D.users.find(u=>u.role==='customer')||D.users[0];if(!u)return empty('Không tìm thấy khách hàng','Kiểm tra lại tài khoản.',link('admin/users','Danh sách khách hàng','btn'));const list=D.orders.filter(o=>o.userId===u.id).slice().reverse();return `<div class="admin-panel">${link('admin/users','← Quay lại danh sách khách hàng','text-link')}<div class="order-head"><div><span class="eyebrow">KHÁCH HÀNG</span><h2>${esc(u.name)}</h2></div><span class="status ${u.locked?'cancelled':'delivered'}">${u.locked?'Đã khóa':'Hoạt động'}</span></div><p><strong>${esc(u.email)}</strong> · ${esc(u.phone||'')}</p><p>${esc(u.address||'')}${u.address&&u.region?', ':''}${esc(u.region||'')}</p><div class="actions"><button class="btn ${u.locked?'':'outline'}" data-act="lock-user" data-id="${u.id}">${u.locked?'Mở khóa':'Khóa'}</button></div></div><div class="admin-panel"><h2>Lịch sử đơn hàng</h2>${orderTable(list)}</div>`;}
function productFormPage(id){S.admin();const p=id?D.products.find(p=>p.id===+id)||{}:{};if(id&&!p.id)return empty('Không tìm thấy thiết kế','Kiểm tra lại mã sản phẩm.',link('admin/products','Danh sách thiết kế','btn'));uploadImage=p.image||'';uploadVersion++;return `<div class="admin-panel">${link('admin/products','← Quay lại danh sách thiết kế','text-link')}<h2>${p.id?'Sửa thiết kế':'Thêm thiết kế mới'}</h2><form id="product-form"><input type="hidden" name="id" value="${p.id||''}">${field('Tên sản phẩm','name',p.name||'','text','required maxlength="120"')}<div class="form-row"><label>Phân loại<select name="category">${opt(S.categories,p.category)}</select></label><label>Bộ sưu tập<select name="collection">${opt(campaigns.map(c=>c[0]),p.collection)}</select></label></div><div class="form-row">${field('Giá bán (₫)','price',p.price||'','number','required min="1" step="1"')}${field('Tồn kho','stock',p.stock??10,'number','required min="0" step="1"')}</div>${field('Chất liệu','material',p.material||'','text','required')}${field('Kích cỡ (cách nhau bằng dấu phẩy)','sizes',(p.sizes||[]).join(','),'text','required placeholder="10,12,14,16,18"')}<label>Mô tả<textarea name="description" required maxlength="800">${esc(p.description||'')}</textarea></label><label>Ảnh sản phẩm (PNG, JPEG hoặc WebP · tối đa 8 MB)<input id="product-upload" type="file" accept="image/png,image/jpeg,image/webp" ${p.id?'':'required'}></label><div id="upload-preview">${p.image?`<img src="${esc(p.image)}" alt="Ảnh hiện tại">`:'Chọn ảnh để xem trước'}</div><p class="form-error" role="alert"></p><div class="actions"><button class="btn">${p.id?'Lưu thay đổi':'Thêm sản phẩm'}</button>${link(p.id?'admin/products/'+p.id:'admin/products','Quay lại','btn outline')}</div></form></div>`;}
function userFormPage(id){S.admin();const u=id?D.users.find(u=>u.id===+id)||{}:{};if(id&&!u.id)return empty('Không tìm thấy khách hàng','Kiểm tra lại tài khoản.',link('admin/users','Danh sách khách hàng','btn'));return `<div class="admin-panel">${link('admin/users','← Quay lại danh sách khách hàng','text-link')}<h2>${u.id?'Chỉnh sửa khách hàng':'Thêm khách hàng'}</h2><form id="user-form"><input type="hidden" name="id" value="${u.id||''}">${field('Họ và tên','name',u.name||'','text','required')}${field('Email hoặc tên đăng nhập','email',u.email||'','text','required')}${field(u.id?'Mật khẩu mới (bỏ trống để giữ nguyên)':'Mật khẩu','password','','password',u.id?'':'required')}${field('Số điện thoại','phone',u.phone||'','tel','required pattern="0[0-9]{9}"')}${field('Địa chỉ','address',u.address||'')}${field('Quận / huyện, tỉnh / thành phố','region',u.region||'')}<p class="form-error" role="alert"></p><div class="actions"><button class="btn">Lưu tài khoản</button>${link(u.id?'admin/users/'+u.id:'admin/users','Quay lại','btn outline')}</div></form></div>`;}
function profileFormPage(){let u;try{u=S.buyer();}catch{return auth();}return `<section class="page narrow"><div class="page-title"><span class="eyebrow">YOUR PROFILE</span><h1>Chỉnh sửa hồ sơ</h1></div><div class="order-card"><form id="profile-form">${field('Họ và tên','name',u.name,'text','required maxlength="80"')}${field('Email hoặc tên đăng nhập','email',u.email,'text','required')}${field('Số điện thoại','phone',u.phone,'tel','required pattern="0[0-9]{9}"')}${field('Địa chỉ','address',u.address,'text','required')}${field('Quận / huyện, tỉnh / thành phố','region',u.region,'text','required')}<p class="form-error" role="alert"></p><div class="actions"><button class="btn">Lưu thay đổi</button>${link('account','Quay lại','btn outline')}</div></form></div></section>`;}
function productForm(id){navigate(id?('admin/products/'+id+'/edit'):'admin/products/new');}
function userForm(id){navigate(id?('admin/users/'+id+'/edit'):'admin/users/new');}
function navigate(path){if(location.hash==='#/'+path)render();else location.hash='/'+path;}
// Hash router: thay nội dung, không tải lại index và không mất bộ nhớ.
function render(){clearInterval(sliderTimer);const raw=String(location.hash||'').replace(/^#?\/?/,'');const [path,query]=raw.split('?');route=path||'';params=new URLSearchParams(query||'');const seg=route.split('/');let content;try{if(seg[0]==='admin'){content=seg[1]==='login'?auth(true):adminPage(seg[1],seg[2],seg[3]);$('#app').innerHTML=seg[1]==='login'||!D.adminId?header()+`<main id="main">${content}</main>`+footer():content;return;}
 switch(seg[0]){case '':content=home();break;case 'catalog':content=catalog();break;case 'search':content=search();break;case 'product':content=product(seg[1]);break;case 'login':content=auth();break;case 'register':content=auth(false,true);break;case 'account':content=seg[1]==='edit'?profileFormPage():account();break;case 'cart':content=cart();break;case 'checkout':content=checkout();break;case 'orders':content=orders(seg[1]);break;case 'success':if(seg[1]&&seg[1]!=='LM1013'){navigate('success/LM1013');return;}content=orders('LM1013',true);break;case 'wishlist':{if(!D.buyerId){content=auth();break;}const favIds=D.favorites.length?D.favorites:[1];const ps=S.filterProducts().filter(p=>favIds.includes(p.id));content=`<section class="page"><div class="page-title"><h1>Những thiết kế bạn yêu thích</h1></div>${ps.length?grid(ps):empty('Chưa có thiết kế yêu thích','Chạm vào trái tim trên mỗi sản phẩm để lưu vào bộ sưu tập của bạn')}</section>`;break;}case 'collections':content=`<section class="page"><div class="page-title"><span class="eyebrow">THE COLLECTIONS</span><h1>Năm sắc thái của vẻ đẹp.</h1></div><div class="collection-grid all">${campaigns.map((_,i)=>collectionCard(i)).join('')}</div></section>`;break;case 'about':case 'guide':case 'policy':content=info(seg[0]);break;default:content=empty('Trang không tồn tại','Hãy quay lại khám phá thế giới LUMIÈRE.');}
 $('#app').innerHTML=header()+`<main id="main" tabindex="-1">${content}</main>`+footer();if(!route){const hero=$('.hero');hero.addEventListener('mouseenter',()=>paused=true);hero.addEventListener('mouseleave',()=>paused=false);hero.addEventListener('focusin',()=>paused=true);hero.addEventListener('focusout',()=>paused=false);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)sliderTimer=setInterval(()=>{if(!paused&&!document.hidden)showSlide(slide+1);},5000);}
 }catch(e){$('#app').innerHTML=header()+`<main id="main">${empty('Không thể mở trang',esc(e.message))}</main>`+footer();}}
// Carousel: thay lớp active và trạng thái trợ năng, vòng lặp 5 ảnh.
function showSlide(n){slide=(n+5)%5;document.querySelectorAll('.slide').forEach((el,i)=>{el.classList.toggle('active',i===slide);el.setAttribute('aria-hidden',String(i!==slide));el.inert=i!==slide;});document.querySelectorAll('.dots button').forEach((el,i)=>{el.classList.toggle('active',i===slide);el.setAttribute('aria-pressed',String(i===slide));});if($('#slide-number'))$('#slide-number').textContent=slide+1;}
// Event delegation cho các nút được tạo lại sau render.
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main')?.focus();return;}const b=e.target.closest('[data-act]');if(!b)return;const id=b.dataset.id;try{switch(b.dataset.act){case 'menu':$('header nav').classList.toggle('open');break;case 'favorite':{if(!requireBuyer())break;const saved=S.toggleFavorite(id);const y=scrollY;render();scrollTo(0,y);toast(!saved?'Đã bỏ khỏi thiết kế yêu thích.':'Đã lưu vào thiết kế yêu thích.');break;}case 'quick-add':navigate('product/'+id);break;case 'zoom':{const p=D.products.find(p=>p.id===+id);modal(`<img class="zoom" src="${esc(p.image)}" alt="${esc(p.name)}"><p>${esc(p.name)}</p>`);break;}case 'confirm-cart':{if(!pendingCart)break;const selection=pendingCart;pendingCart=null;b.disabled=true;try{if(selection.userId!==D.buyerId)throw Error('Tài khoản đã thay đổi. Hãy chọn lại sản phẩm.');S.addCart(selection.id,selection.size,selection.qty);}catch(err){$('#dialog').close();throw err;}$('#dialog').close();render();modal(`<h2>Đã thêm sản phẩm vào giỏ hàng!</h2><div class="actions">${link('cart','Xem giỏ hàng','btn')}<button class="btn outline" data-act="close">Tiếp tục mua sắm</button></div>`);break;}case 'edit-profile':navigate('account/edit');break;case 'cancel-order':modal(`<h2>Bạn có chắc chắn muốn hủy đơn hàng này không?</h2><div class="actions"><button class="btn outline" data-act="close">Quay lại</button><button class="btn" data-act="confirm-cancel" data-id="${esc(id)}">Xác nhận hủy</button></div>`);break;case 'confirm-cancel':S.cancelOrder(id);$('#dialog').close();navigate('orders');success('Đã hủy đơn hàng thành công.');break;case 'close':pendingCart=null;$('#dialog').close();break;case 'prev':showSlide(slide-1);break;case 'next':showSlide(slide+1);break;case 'slide':showSlide(+id);break;case 'pause':{if(sliderTimer){clearInterval(sliderTimer);sliderTimer=null;b.textContent='▷';b.setAttribute('aria-label','Tiếp tục banner');}else{sliderTimer=setInterval(()=>{if(!paused&&!document.hidden)showSlide(slide+1);},5000);b.textContent='Ⅱ';b.setAttribute('aria-label','Dừng chuyển banner');}break;}case 'qty':S.changeCart(+id,+b.dataset.value);render();break;case 'remove-cart':S.removeCart(+id);render();toast('Đã xóa sản phẩm khỏi giỏ.');break;case 'logout':S.logout();pendingCart=null;navigate('login');toast('Đã đăng xuất.');break;case 'admin-logout':S.logout('admin');navigate('admin/login');toast('Đã đăng xuất quản trị.');break;case 'edit-product':navigate(id?('admin/products/'+id+'/edit'):'admin/products/new');break;case 'show-product':S.showProduct(id);navigate('admin/products');toast('Đã hiển thị lại sản phẩm.');break;case 'hide-product':modal(`<h2>Xác nhận ẩn sản phẩm?</h2><div class="actions"><button class="btn outline" data-act="close">Giữ lại</button><button class="btn" data-act="confirm-hide" data-id="${id}">Xác nhận ẩn</button></div>`);break;case 'delete-product':modal(`<h2>Xác nhận xóa sản phẩm?</h2><div class="actions"><button class="btn outline" data-act="close">Giữ lại</button><button class="btn" data-act="confirm-delete" data-id="${id}">Xác nhận xóa</button></div>`);break;case 'confirm-hide':S.hideProduct(id);$('#dialog').close();navigate('admin/products');toast('Đã ẩn sản phẩm.');break;case 'confirm-delete':{const result=S.removeProduct(id,true);$('#dialog').close();navigate('admin/products');toast(result==='hidden'?'Sản phẩm đã có trong đơn hàng: chỉ ẩn khỏi cửa hàng, giữ nguyên lịch sử.':'Đã xóa sản phẩm.');break;}case 'edit-user':navigate(id?('admin/users/'+id+'/edit'):'admin/users/new');break;case 'lock-user':{const u=D.users.find(u=>u.id===+id);if(u&&u.locked){modal(`<h2>Xác nhận mở khóa?</h2><div class="actions"><button class="btn outline" data-act="close">Giữ lại</button><button class="btn" data-act="confirm-lock" data-id="${id}">Xác nhận</button></div>`);}else{modal(`<h2>Xác nhận khóa?</h2><div class="actions"><button class="btn outline" data-act="close">Giữ lại</button><button class="btn" data-act="confirm-lock" data-id="${id}">Xác nhận</button></div>`);}break;}case 'confirm-lock':{const u=S.lockUser(id);$('#dialog').close();navigate('admin/users');toast(u.locked?'Đã khóa tài khoản.':'Đã mở khóa tài khoản.');break;}case 'status':modal(`<h2>Xác nhận cập nhật đơn ${esc(id)}?</h2><p>Chuyển sang: ${statuses[b.dataset.value]}. Không thể chuyển ngược.</p><div class="actions"><button class="btn outline" data-act="close">Quay lại</button><button class="btn" data-act="confirm-status" data-id="${esc(id)}" data-value="${b.dataset.value}">Xác nhận</button></div>`);break;case 'confirm-status':S.transition(id,b.dataset.value);$('#dialog').close();navigate('admin/orders');toast('Đã cập nhật trạng thái đơn hàng.');break;}}catch(err){toast(err.message);}});
// FormData lấy dữ liệu; lỗi nghiệp vụ hiển thị tại form hoặc toast.
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));const err=form.querySelector('.form-error');if(err)err.textContent='';const cleanNum=v=>String(v??'').replace(/\D/g,'');try{switch(form.getAttribute('id')){case 'quick-search':navigate('search');success('Đã tìm kiếm thành công.');break;case 'search-filters':navigate('search');success('Đã tìm kiếm thành công.');break;case 'filters':navigate('search');success('Đã tìm kiếm thành công.');break;case 'login':S.login(data.email,data.password);navigate(returnAfterLogin||(route==='checkout'?'checkout'+(params.get('mode')==='buy-now'?'?mode=buy-now':''):'account'));returnAfterLogin='';toast('Chào mừng bạn đến LUMIÈRE.');break;case 'admin-login':S.login(data.email,data.password,'admin');navigate('admin/dashboard');break;case 'register':{const u=S.saveUser(data);S.login(u.email,data.password);navigate(returnAfterLogin||'account');returnAfterLogin='';toast('Đã tạo tài khoản.');break;}case 'add-cart':{if(!requireBuyer())break;const buy=e.submitter?.name==='buy';S.validateSelection(data.id,data.size,+data.qty,!buy);if(buy){S.startBuyNow(data.id,data.size,+data.qty);navigate('checkout?mode=buy-now');}else{pendingCart={userId:D.buyerId,id:+data.id,size:data.size,qty:+data.qty};const p=D.products.find(p=>p.id===+data.id);modal(`<h2>Bạn có muốn thêm sản phẩm này vào giỏ hàng?</h2><div class="cart-row"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><p>Size ${esc(data.size)} · Số lượng ${+data.qty}</p><strong>${money(p.price*data.qty)}</strong></div></div><div class="actions"><button class="btn outline" data-act="close">Hủy</button><button class="btn" data-act="confirm-cart">Xác nhận thêm</button></div>`);}break;}case 'checkout':{const u0=S.buyer();const merged={...data};for(const k of ['name','phone','email','address','region'])if(!String(merged[k]||'').trim())merged[k]=u0[k]||'';const o=S.checkout(merged,params.get('mode')==='buy-now');lastSuccess=o;navigate('success/LM1013');success('Đã đặt hàng thành công. Cảm ơn bạn đã chọn LUMIÈRE.');break;}case 'profile-form':S.saveProfile(data);navigate('account');toast('Đã lưu thông tin cá nhân.');break;case 'newsletter':newsletter=data.email.trim();toast('LUMIÈRE đã lắng nghe');form.reset();break;case 'product-form':{const saved=S.saveProduct({...data,image:uploadImage},data.id||null);navigate('admin/products');toast('Đã lưu sản phẩm.');break;}case 'user-form':{const saved=S.saveUser({...data,byAdmin:true},data.id||null);navigate('admin/users');toast('Đã lưu tài khoản.');break;}case 'admin-search':success('Đã lọc thành công.');navigate('admin/products');break;case 'admin-user-search':success('Đã lọc thành công.');navigate('admin/users');break;case 'order-filter':case 'stats-filter':navigate((form.getAttribute('id')==='order-filter'?'admin/orders?':'admin/stats?')+new URLSearchParams(data));break;}}catch(error){if(err)err.textContent=error.message;else toast(error.message);}});
document.addEventListener('input',e=>{if(e.target&&e.target.matches&&e.target.matches('[data-price]')){const d=String(e.target.value||'').replace(/\D/g,'').slice(0,12);e.target.value=d?Number(d).toLocaleString('vi-VN'):'';}});
document.addEventListener('change',e=>{if(e.target.name==='payment'){const box=$('#qr-box');if(box)box.hidden=e.target.value!=='qr';}if(e.target.id==='address-choice'){const form=$('#checkout'),u=S.buyer(),saved=e.target.value==='saved';for(const k of ['name','phone','email','address','region']){if(form.elements[k]){if(saved)form.elements[k].value=u[k]||'';form.elements[k].disabled=saved;}}if(!saved)form.elements.name.focus();}if(e.target.id==='product-upload'){const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>8*1024*1024){toast('Chọn ảnh PNG, JPEG hoặc WebP tối đa 8 MB.');e.target.value='';return;}const token=++uploadVersion,button=$('#product-form button.btn');button.disabled=true;const reader=new FileReader();const failed=()=>{if(token!==uploadVersion)return;button.disabled=false;toast('Không đọc được ảnh. Hãy chọn file PNG, JPEG hoặc WebP hợp lệ.');e.target.value='';};reader.onerror=failed;reader.onload=()=>{if(token!==uploadVersion)return;const check=new Image();check.onload=()=>{if(token!==uploadVersion||!$('#upload-preview'))return;uploadImage=reader.result;$('#upload-preview').innerHTML=`<img src="${uploadImage}" alt="Ảnh xem trước">`;button.disabled=false;};check.onerror=failed;check.src=reader.result;};reader.readAsDataURL(f);}});
window.addEventListener('hashchange',()=>{if($('#dialog').open)$('#dialog').close();render();scrollTo(0,0);});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render();

function requireBuyer(){try{S.buyer();return true;}catch{returnAfterLogin=route+(params.toString()?'?'+params:'');navigate('login');toast('Vui lòng đăng nhập để tiếp tục.');return false;}}
function profileForm(){navigate('account/edit');}
window.addEventListener('storage',e=>{if(e.key==='lumiere_state_v2'){try{S.refresh();pendingCart=null;if($('#dialog').open)$('#dialog').close();render();}catch(err){toast(err.message);}}});
if(S.storageError)toast(S.storageError);
